 fs.mkdirSync(path.join(work,'cas'),{recursive:true});for(const o of cas.values()){const file=path.join(work,'cas',o.sha256);if(fs.existsSync(file)){const b=fs.readFileSync(file);if(hash(b)!==o.sha256||b.length!==o.bytes.length)throw Error('Conflicting CAS object');}else fs.writeFileSync(file,o.bytes);}
